    $(el, "[data-b]").addEventListener("click", function () { com = !com; M = []; this.textContent = "Balance : " + (com ? "celle du commerçant (0,8 kg à vide)" : "celle de Samuel (tarée)"); maj(); });
    $(el, "[data-z]").addEventListener("click", function () { M = []; maj(); });
