    for (k = 0; k < 25; k++) { var i = k % 5, j = Math.floor(k / 5); o.push({ f: "boite", c: [-80 + i * 40, -9, -80 + j * 40], d: [40, 2, 40], coul: C[(i + j) % 4], dessus: C[(i + 2 * j) % 4], div: false }); }
