          var s = "<rect width='640' height='230' fill='#FBF8F2'/>";
          s += "<rect x='30' y='40' width='170' height='90' rx='14' fill='" + BLEU + "'/>" + txt(115, 72, "φιλεῖν", { s: 24, c: "#fff" }) + txt(115, 96, "philein", { s: 13, c: "#DCE6F2", i: true }) + txt(115, 116, "aimer", { s: 13, c: "#F7C948" });
