          s += "<rect x='90' y='40' width='200' height='56' rx='10' fill='#fff' stroke='#C9D2E3'/>" + txt(190, 62, "Cameroun", { s: 12, c: VERT }) + txt(190, 84, "≈ 5 M (1960) → ≈ 29 M (auj.)", { s: 11, w: 600 });
